<?php
declare(strict_types=1);
$private=sys_get_temp_dir().'/ectro-personas-'.bin2hex(random_bytes(6));mkdir($private,0700);putenv('APP_DATA_DIR='.$private);putenv('APP_ENV=development');putenv('APP_KEY='.base64_encode(random_bytes(32)));
register_shutdown_function(function()use($private){$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($private,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $file)$file->isDir()?rmdir($file->getPathname()):unlink($file->getPathname());rmdir($private);});
require __DIR__.'/../app/bootstrap.php';require __DIR__.'/../app/templates.php';require __DIR__.'/../app/mysql.php';require __DIR__.'/../app/lab-api.php';
$fixtures=json_decode(stream_get_contents(STDIN),true,64,JSON_THROW_ON_ERROR);$checks=0;
function personaCheck(bool $condition,string $why):void{global $checks;if(!$condition)throw new RuntimeException($why);$checks++;}
function personaReject(int $status,callable $fn):void{try{$fn();throw new RuntimeException('Expected '.$status);}catch(ApiError $error){personaCheck($error->status===$status,$error->getMessage());}}
function personaUser(string $name):array{$id=id();query('INSERT INTO users(id,name,email,password,role,created_at) VALUES(?,?,?,?,?,?)',[$id,$name,$name.'@example.test','unused','user',now()]);return one('SELECT * FROM users WHERE id=?',[$id]);}
$alice=personaUser('alice');$bob=personaUser('bob');$pid=createProject($alice,'Personas','web');$other=createProject($alice,'Other','web');$before=workspaceBytes(project($alice,$pid));
foreach($fixtures as $model=>$content){$saved=studioPersonaSave($alice,['project'=>$pid,'content'=>$content]);personaCheck($saved['content']['model']===$model&&$saved['version']===1,'Frontend model persists');personaCheck($saved['content']['fields']['thinks']===$content['fields']['thinks'],'Hidden model fields are retained');$profiles[$model]=$saved;}
$p=$profiles['simple'];personaCheck(workspaceBytes(project($alice,$pid))>$before,'Personas count toward workspace quota');
personaReject(404,fn()=>studioPersonaGet($alice,$other,$p['id']));personaReject(404,fn()=>studioPersonaGet($bob,$pid,$p['id']));personaReject(404,fn()=>studioPersonaSave($alice,['project'=>$other,'id'=>$p['id'],'version'=>1,'content'=>$p['content']]));personaReject(409,fn()=>studioPersonaSave($alice,['project'=>$pid,'id'=>$p['id'],'version'=>0,'content'=>$p['content']]));
foreach([['model'=>'invalid'],['name'=>str_repeat('x',181)],['fields'=>['__proto__'=>'x']],['basis'=>'supported','evidence'=>[]],['evidence'=>[['source'=>'Interview','note'=>'']]],['evidence'=>array_fill(0,7,['source'=>'x','note'=>'y'])]] as $bad)personaReject(422,fn()=>studioPersonaContent([...$p['content'],...$bad]));
$supported=studioPersonaContent([...$p['content'],'basis'=>'supported','evidence'=>[['source'=>'Synthetisches Interview','note'=>'Eine konkrete Beobachtung.']]]);personaCheck($supported['basis']==='supported','Documented evidence is accepted');
$journey=labSave($alice,['project'=>$pid,'kind'=>'journey','name'=>'Persona Journey','content'=>['persona'=>array_intersect_key($p['content'],array_flip(['name','goal','context'])),'personaRef'=>['id'=>$p['id'],'version'=>1],'personaSnapshot'=>$p['content'],'stages'=>[]]]);
$updated=studioPersonaSave($alice,['project'=>$pid,'id'=>$p['id'],'version'=>1,'content'=>[...$p['content'],'goal'=>'Ein neues Ziel']]);personaCheck(labObject($alice,$journey['id'])['content']['persona']['goal']!==$updated['content']['goal'],'Library edits never rewrite journey perspective');personaCheck(labObject($alice,$journey['id'])['content']['personaRef']['version']===1,'Snapshot retains original revision');
$archive=studioPersonaArchive($alice,['project'=>$pid,'id'=>$p['id'],'version'=>2,'archived'=>true]);personaCheck($archive['archived']&&$archive['version']===3,'Archive is versioned');personaReject(409,fn()=>studioPersonaArchive($alice,['project'=>$pid,'id'=>$p['id'],'version'=>2,'archived'=>false]));personaCheck(labObject($alice,$journey['id'])['content']['personaSnapshot']['name']===$p['content']['name'],'Archive preserves journey snapshot');$restored=studioPersonaArchive($alice,['project'=>$pid,'id'=>$p['id'],'version'=>3,'archived'=>false]);personaCheck(!$restored['archived']&&$restored['version']===4,'Archive can be reversed');
$catalog=studioPersonas($alice,$pid);personaCheck(count($catalog['personas'])===5&&$catalog['journeys'][0]['personaId']===$p['id'],'Library exposes same-project usage');
personaReject(422,fn()=>labValidate('journey',['persona'=>[],'stages'=>[],'personaRef'=>['id'=>$p['id'],'version'=>1]]));
$gid=id();query('INSERT INTO groups(id,name,created_at) VALUES(?,?,?)',[$gid,'Shared',now()]);foreach([$alice,$bob] as $u)query('INSERT INTO group_members VALUES(?,?)',[$gid,$u['id']]);$shared=createProject($alice,'Shared personas','web',$gid);$groupPersona=studioPersonaSave($alice,['project'=>$shared,'content'=>$p['content']]);personaCheck(studioPersonaGet($bob,$shared,$groupPersona['id'])['id']===$groupPersona['id'],'Group members share project library');$groupPersona=studioPersonaSave($bob,['project'=>$shared,'id'=>$groupPersona['id'],'version'=>1,'content'=>[...$p['content'],'tagline'=>'Team edit']]);personaCheck($groupPersona['version']===2,'Group edits are versioned');query('DELETE FROM group_members WHERE group_id=? AND user_id=?',[$gid,$bob['id']]);personaReject(404,fn()=>studioPersonas($bob,$shared));
query('UPDATE users SET features=? WHERE id=?',[json_encode(['journey_lab'=>false]),$alice['id']]);$blocked=one('SELECT * FROM users WHERE id=?',[$alice['id']]);personaReject(403,fn()=>studioPersonas($blocked,$pid));personaReject(403,fn()=>studioPersonaSave($blocked,['project'=>$pid,'content'=>$p['content']]));personaReject(403,fn()=>studioPersonaArchive($blocked,['project'=>$pid,'id'=>$p['id'],'version'=>4,'archived'=>true]));query('UPDATE users SET features="{}" WHERE id=?',[$alice['id']]);query('UPDATE lab_project_config SET config=? WHERE project_id=?',[json_encode(['tools'=>['dataset'],'entry'=>'dataset']),$other]);personaReject(403,fn()=>studioPersonas($alice,$other));
for($i=5;$i<20;$i++)studioPersonaSave($alice,['project'=>$pid,'content'=>[...$p['content'],'name'=>'Persona '.$i]]);personaReject(413,fn()=>studioPersonaSave($alice,['project'=>$pid,'content'=>$p['content']]));
$probe=createProject($alice,'Cascade','web');$probeProfile=studioPersonaSave($alice,['project'=>$probe,'content'=>$p['content']]);query('DELETE FROM projects WHERE id=?',[$probe]);personaCheck(!one('SELECT id FROM lab_personas WHERE id=?',[$probeProfile['id']]),'Project deletion cascades to personas');personaCheck(!db()->query('PRAGMA foreign_key_check')->fetch(),'Foreign keys remain consistent');
echo "$checks persona validation, snapshots, archives, permissions, quota, shared access and isolation checks passed.\n";
